&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Left&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:null,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;OrderIndex&quot;:0,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;/* ========= CSAG (SQL Server) -&amp;gt; writes to app.CalculAgent ========= */\n\n;WITH Brut AS (\n    SELECT\n        a.Marca,\n\n        /* Brut fără cod E */\n        SUM(\n            CASE\n                WHEN UPPER(a.CodPrestatie) &amp;lt;&amp;gt; &#39;E&#39; AND ISNULL(a.Procent, 0) &amp;lt;&amp;gt; 0\n                    THEN a.Suma * a.Procent\n                WHEN UPPER(a.CodPrestatie) &amp;lt;&amp;gt; &#39;E&#39; AND ISNULL(a.Procent, 0) = 0\n                    THEN CAST(ISNULL(p.SumaFixa, 0) AS DECIMAL(18,6)) * ISNULL(a.Suma, 0)\n                ELSE 0\n            END\n        ) AS BrutFaraE,\n\n        /* Tutun (cod E) */\n        SUM(\n            CASE\n                WHEN UPPER(a.CodPrestatie) = &#39;E&#39;\n                    THEN ISNULL(a.Suma, 0) * ISNULL(a.Procent, 0)\n                ELSE 0\n            END\n        ) AS Tutun\n\n    FROM app.Agent a\n    LEFT JOIN app.TSPrestatie p\n           ON p.CodSucursala = a.CodSucursala\n          AND p.CodPrestatie = a.CodPrestatie\n    WHERE a.CodSucursala = @CodSucursala\n      AND a.AnSesiuneCurenta = @An\n      AND a.LunaSesiuneCurenta = @Luna\n    GROUP BY a.Marca\n),\nCuTransa AS (\n    SELECT\n        b.*,\n        t.LimitaInferioara AS LimiCurenta,\n        t.Procent          AS ProcCurent\n    FROM Brut b\n    OUTER APPLY (\n        SELECT TOP 1\n            l.LimitaInferioara,\n            l.LimitaSuperioara,\n            l.Procent\n        FROM app.LimitaPrestatiiAg l\n        WHERE b.BrutFaraE &amp;gt;= l.LimitaInferioara\n          AND b.BrutFaraE &amp;lt;= ISNULL(l.LimitaSuperioara, 2147483647)\n        ORDER BY l.LimitaInferioara DESC\n    ) t\n),\nSel1 AS (\n    SELECT\n        x.Marca,\n        SUM(\n            (CAST(ISNULL(l.LimitaSuperioara, l.LimitaInferioara) AS DECIMAL(18,6)) - CAST(l.LimitaInferioara AS DECIMAL(18,6)) + 1)\n            * ISNULL(l.Procent, 0)\n        ) AS Sel1\n    FROM CuTransa x\n    JOIN app.LimitaPrestatiiAg l\n      ON l.LimitaInferioara &amp;lt; x.LimiCurenta\n    GROUP BY x.Marca\n),\nRezultat AS (\n    SELECT\n        x.Marca,\n        x.BrutFaraE,\n        ISNULL(s.Sel1, 0) AS Sel1,\n        x.LimiCurenta,\n        x.ProcCurent,\n        x.Tutun,\n        /* comision progresiv */\n        CASE\n            WHEN x.LimiCurenta IS NULL OR x.ProcCurent IS NULL THEN 0\n            ELSE (x.BrutFaraE - x.LimiCurenta) * x.ProcCurent + ISNULL(s.Sel1, 0)\n        END AS ComisionProgresiv,\n        /* total final */\n        CASE\n            WHEN x.LimiCurenta IS NULL OR x.ProcCurent IS NULL THEN 0\n            ELSE (x.BrutFaraE - x.LimiCurenta) * x.ProcCurent + ISNULL(s.Sel1, 0)\n        END + x.Tutun AS TotalFinal\n    FROM CuTransa x\n    LEFT JOIN Sel1 s ON s.Marca = x.Marca\n)\n\n/* Upsert into app.CalculAgent */\nMERGE app.CalculAgent AS tgt\nUSING (\n    SELECT\n        @CodSucursala AS CodSucursala,\n        @An           AS AnSesiune,\n        @Luna         AS LunaSesiune,\n        Marca,\n        CAST(ROUND(TotalFinal, 0) AS INT) AS TotalFinalInt\n    FROM Rezultat\n) AS src\nON  tgt.CodSucursala = src.CodSucursala\nAND tgt.AnSesiune    = src.AnSesiune\nAND tgt.LunaSesiune  = src.LunaSesiune\nAND tgt.Marca        = src.Marca\n\nWHEN MATCHED THEN\n    UPDATE SET\n        tgt.Suma = src.TotalFinalInt,\n        tgt.LastModifiedDate = SYSDATETIMEOFFSET(),\n        tgt.LastModifiedBy = @UserId\n\nWHEN NOT MATCHED THEN\n    INSERT (CodSucursala, AnSesiune, LunaSesiune, Marca, Suma, CreatedDate, CreatedBy)\n    VALUES (src.CodSucursala, src.AnSesiune, src.LunaSesiune, src.Marca, src.TotalFinalInt,\n            SYSDATETIMEOFFSET(), @UserId);\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;An&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[User:UserId]&quot;,&quot;name&quot;:&quot;UserId&quot;}],&quot;OutputTokenName&quot;:&quot;&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false},{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:null,&quot;ActionType&quot;:&quot;RedirectToPage&quot;,&quot;OrderIndex&quot;:1,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;PageId&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:187,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;EnforceCurrentLocale&quot;:&quot;&quot;,&quot;QueryString&quot;:&quot;&quot;,&quot;QueryStringUseUrlProvider&quot;:true,&quot;OpenInPopup&quot;:&quot;&quot;,&quot;PopupTitle&quot;:&quot;&quot;,&quot;OpenInNewTab&quot;:&quot;&quot;},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;Url&quot;:&quot;&amp;amp;buttonName=Calculsume&quot;,&quot;ModuleId&quot;:864,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;Calculsume&quot;,&quot;Title&quot;:&quot;Calcul sume&quot;,&quot;Help&quot;:null,&quot;ShowCondition&quot;:null,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:2,&quot;CssClass&quot;:&quot;default&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:true,&quot;PermissionsExportJson&quot;:&quot;[]&quot;,&quot;Permissions&quot;:[],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:&quot;Are you sure you want to do this?&quot;,&quot;ConfirmationOk&quot;:&quot;Yes, pretty sure&quot;,&quot;ConfirmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false}]&lt;/GridButtons&gt;
